/** A spec generated by the worker from the blueprint's workbook must boot, load and calculate here. */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import { afterAll, beforeAll, describe, expect, it } from "vitest";

import { createApp } from "../src/app.js";
import { parseSpec } from "../src/spec/loader.js";
import { Client, newDatabase, PASSWORD } from "./helpers.js";

const root = new URL("../../../packages/spec/fixtures/generated/", import.meta.url);
const spec = parseSpec(JSON.parse(readFileSync(new URL("daftar.spec.json", root), "utf8")));
const seedDir = fileURLToPath(new URL("seed/", root));
const config = { secret: "s", timezone: "Africa/Algiers", processor: undefined };

describe("the generated tutoring app", () => {
  let owner: Client;
  let close: () => Promise<void>;
  let boot: () => Promise<void>;
  const payments = spec.entities.find((item) => item.period)?.key as string;

  beforeAll(async () => {
    const { db, drop } = await newDatabase();
    const app = await createApp({ spec, db, config, seedDir });
    await app.listen(0, "127.0.0.1");
    const base = (await app.getUrl()).replace("[::1]", "127.0.0.1");
    owner = new Client(base);
    boot = async () => {
      const again = await createApp({ spec, db, config, seedDir });
      await again.close().catch(() => undefined);
    };
    close = async () => {
      await app.close();
      await drop();
    };
    await owner.post("/api/auth/setup", { username: "owner", password: PASSWORD });
  });
  afterAll(() => close());

  it("loads the accepted data once, on first start", async () => {
    expect((await owner.get("/api/e/eleves")).body.total).toBe(16);
    expect((await owner.get(`/api/e/${payments}`)).body.total).toBe(36);
    expect((await owner.get("/api/e/parent")).body.total).toBe(4);
    await boot();
    expect((await owner.get("/api/e/eleves")).body.total).toBe(16);
  });

  it("merges the retyped parents and links every student", async () => {
    const parents = (await owner.get("/api/e/parent")).body.rows;
    const ids = new Set(parents.map((row: any) => row._id));
    const students = (await owner.get("/api/e/eleves?pageSize=50")).body.rows;
    expect(students.every((row: any) => ids.has(row.parent))).toBe(true);
  });

  it("links the payments to students through their matricule", async () => {
    const students = new Map((await owner.get("/api/e/eleves?pageSize=50")).body.rows.map((row: any) => [row._id, row.matricule]));
    const rows = (await owner.get(`/api/e/${payments}?pageSize=50&sort=period`)).body.rows;
    expect(rows.every((row: any) => students.has(row.matricule))).toBe(true);
  });

  it("computes the same totals as the workbook's total rows", async () => {
    // Each month: due = sum(3000 + i*100), paid = sum(1000 + i*50), for i in 0..11.
    const dueAMonth = 12 * 3000 + 100 * 66;
    const paidAMonth = 12 * 1000 + 50 * 66;
    const january = (await owner.get(`/api/e/${payments}?filter.period=2026-01-01&totals=du,paye,reste`)).body.totals;
    expect(january).toEqual({ du: dueAMonth, paye: paidAMonth, reste: dueAMonth - paidAMonth });
    const all = (await owner.get(`/api/e/${payments}?totals=reste`)).body.totals;
    expect(all.reste).toBe(3 * (dueAMonth - paidAMonth));
  });

  it("recomputes after an edit, and the edit lands in history", async () => {
    const [row] = (await owner.get(`/api/e/${payments}?pageSize=1`)).body.rows;
    const updated = (await owner.patch(`/api/e/${payments}/${row._id}`, { paye: row.du })).body;
    expect(updated.reste).toBe(0);
    const history = (await owner.get(`/api/e/${payments}/${row._id}/history`)).body.changes;
    expect(history[0].changes.paye).toEqual([row.paye, row.du]);
    expect(history.at(-1)).toMatchObject({ op: "create", source: "import", actor: "system" });
  });

  it("runs the calculator with Excel's stored result as its test case", async () => {
    const calculator = spec.calculators[0]!;
    const result = (await owner.post(`/api/calc/${calculator.key}`, calculator.testCases[0]!.inputs)).body;
    expect(result.outputs).toEqual(calculator.testCases[0]!.outputs);
  });

  it("lists the personal data in the register", async () => {
    const register = (await owner.get("/api/register")).body;
    const fields = register.personalData.flatMap((item: any) => item.fields.map((entry: any) => entry.key));
    expect(fields).toContain("telephone_parent");
  });

});

describe("undoing a seed load", () => {
  it("removes all of it as one batch, children before what they link to", async () => {
    const { db, drop } = await newDatabase();
    const app = await createApp({ spec, db, config, seedDir });
    await app.listen(0, "127.0.0.1");
    try {
      const owner = new Client((await app.getUrl()).replace("[::1]", "127.0.0.1"));
      await owner.post("/api/auth/setup", { username: "owner", password: PASSWORD });
      const [row] = (await owner.get("/api/e/parent?pageSize=1")).body.rows;
      const { batchId } = (await owner.get(`/api/e/parent/${row._id}/history`)).body.changes.at(-1);
      const undo = await owner.post(`/api/batches/${batchId}/undo`);
      expect(undo.status).toBe(200);
      expect(undo.body.undone).toBe(56);
      for (const entity of spec.entities) expect((await owner.get(`/api/e/${entity.key}`)).body.total).toBe(0);
    } finally {
      await app.close();
      await drop();
    }
  });
});
